def translate(text):
    # Apply in one pass: replacements must not accidentally translate German labels
    # or identifiers such as perfekt in subsequent passes.
    import re
    pattern = '|'.join(re.escape(k) for k in sorted(TEXT, key=len, reverse=True))
    return re.sub(pattern, lambda m: TEXT[m.group()], text)
